</script>
```

#### 在actions中定义函数，用于调用mutation

安装axios：`npm install axios`

定义actions函数：

```js
import Vue from 'vue'
import Vuex from 'vuex'
import axios from 'axios'

Vue.use(Vuex) 

export default new Vuex.Store({
  //共享数据
  state: {
    name: "未登录游客"

  },
  getters: {

  },

  //修改共享数据时只能通过mutation实现，必须是同步操作
  mutations: {
    setName(state,name){
      state.name = name
    }
  },

  //通过action可以调用到mutation，action中可以进行异步操作
  actions: {
    setNameByAxios(context){
      axios({
        url: '/api/admin/employee/login',
        method: 'post',
        data: {
          username: "admin",
          password: '123456'
        }
      }).then(res => {
        if(res.data.code == 1){
          //异步请求后，需要修改共享数据
          // actions中调用mutation定义的函数setName
          context.commit('setName', res.data.data.name)
        }
      })
    }
  },
  modules: {
  }
})

```

App.vue中使用

```vue
<template>
  <div id="app">
    <input type='button' value="员工登录换名" @click="handleLogin"/>
  </div>
</template>


<script>
  export default {
    name: "App",
    methods: {
      handleLogin(){
        // 调用actions当中的函数 setNameByAxios
        this.$store.dispatch('setNameByAxios')
      }
    }
  }


</script>
```

