### 等待唤醒

```java
package com.thread.itcast;

import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ConsumerAndProducer {
    public static void main(String[] args) {

        Thread consumer = new Thread(new Runnable() {
            public void run() {
                while (true) {
                    synchronized (Buffer.lock) {
                        if(Buffer.count == 0){
                            break;
                        }else {
                            if(Buffer.bufferFlag == 0){
                                try {
                                    Buffer.lock.wait();
                                } catch (InterruptedException e) {
                                    throw new RuntimeException(e);
                                }
                            }else {
                                System.out.println("消费者消费 " + (11 - Buffer.count--));
                                Buffer.bufferFlag = 0;
                                Buffer.lock.notifyAll();
                            }
                        }
                    }
                }
            }
        });
        Thread producer = new Thread(new Runnable() {
            public void run() {
                while (true) {
                    synchronized (Buffer.lock) {
                        if(Buffer.count == 0){
                            break;
                        }else {
                            if(Buffer.bufferFlag == 0){
                                System.out.println("生产者生产第 " + (11 - Buffer.count));
                                Buffer.bufferFlag = 1;
                                Buffer.lock.notifyAll();

                            }else {
                                try {
                                    Buffer.lock.wait();
                                } catch (InterruptedException e) {
                                    throw new RuntimeException(e);
                                }
                            }
                        }
                    }
                }
            }
        });
        consumer.start();
        producer.start();

    }
}

class Buffer{
    public static final Object lock = new Object();
    public static int bufferFlag = 0; //状态为0消费者和生产才能进行
    public static int count = 10; // 消费次数

}


```



### 等待唤醒机制（阻塞队列）

```java
package com.thread.itcast;

import java.util.concurrent.ArrayBlockingQueue;

public class QueueBuffer {
    public static void main(String[] args) {



        Thread producer = new Thread(
                new MyRunnable() {
                    @Override
                    public void run() {
                        int i = 10;
                        while (i > 0) {
                            System.out.println("生产者生产" + (11 - i) );
                            try {
                                queue.put("产品" + (11 - i)); // 队列已自己加锁

                            } catch (InterruptedException e) {
                                throw new RuntimeException(e);
                            }

                            i--;
                        }
                        try {
                            Thread.sleep(10);
                        } catch (InterruptedException e) {
                            throw new RuntimeException(e);
                        }
                        System.out.println("生产完成");

                    }
                }
        );
        Thread consumer = new Thread(new MyRunnable() {

            @Override
            public void run() {
                while (true) {
                    //System.out.println("开始消费");
                    String poll = null;
                    try {
                        poll = queue.take();
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                    System.out.println("消费者消费" + poll);
                }

            }
        });
        consumer.setDaemon(true);
        producer.start();
        consumer.start();

    }
}


abstract class MyRunnable implements Runnable {
    protected static ArrayBlockingQueue<String> queue = new ArrayBlockingQueue<>(10);

}



```



